SELECT ((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='funnel_configurations' AND ENGINE='InnoDB' AND TABLE_COLLATION='utf8mb4_unicode_ci')=1
AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='funnel_configurations')=14
AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='funnel_configurations' AND COLUMN_NAME IN ('id','tenant_id','branch_id','industry_channel_id','channel_version_id','review_destination_id','revision','status','brand_title','accent_hex','locale','published_at','created_at','updated_at'))=14
AND (SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='funnel_configurations' AND CONSTRAINT_NAME IN ('uq_funnel_revision','uq_funnel_owner','uq_funnel_channel','fk_funnel_branch','fk_funnel_version','fk_funnel_destination','ck_funnel_revision','ck_funnel_color','ck_funnel_publish'))=9) AS satisfied
